  /*
   * Small wrapper to extract total length of a file
   */
  func unxz_len(_ fd : FileDescriptor) -> UInt {
    var xfi = xz_file_info()
    if (!parse_indexes(&xfi, fd)) {
      let res = lzma_index_uncompressed_size(xfi.idx)
      lzma_index_end(xfi.idx, nil)
      return UInt(res)
    }
    return 0
  }

